23	/**
24	 * An OffscreenLayer encapsulates a "child surface" onto which canvas draw calls can be issued.
25	 * At the end, the result of these draw calls will be composited onto the parent surface, with
26	 * user-provided alpha, blend mode, color filter, and drop shadow.
27	 * <p>
28	 * To use the OffscreenLayer, call its start() method with the necessary parameters, draw
29	 * to the returned canvas, and then call finish() to composite the result onto the main canvas.
30	 * <p>
31	 * In this sense, using an OffscreenLayer is very similar to the Canvas.saveLayer() family
32	 * of functions, and in fact forwards to Canvas.saveLayer() when appropriate.
33	 * <p>
34	 * Unlike Canvas.saveLayer(), an OffscreenLayer also supports compositing with a drop-shadow,
35	 * and uses a hardware-accelerated target when available. It attempts to choose the fastest
36	 * approach to render and composite the contents, up to and including simply rendering
37	 * directly, if possible.
38	 */
39	public class OffscreenLayer {
40	  /**
41	   * Encapsulates configuration for compositing the layer contents on the parent. Similar to
42	   * Paint, but only includes operations that the OffscreenLayer can support.
43	   */
44	  public static class ComposeOp {
45	    public int alpha;
46	    @Nullable public BlendModeCompat blendMode;
47	    @Nullable public ColorFilter colorFilter;
48	    @Nullable public DropShadow shadow;
49	
50	    public ComposeOp() {
51	      reset();
52	    }
53	
54	    public boolean isTranslucent() {
55	      return alpha < 255;
56	    }
57	
58	    public boolean hasBlendMode() {
59	      return blendMode != null && blendMode != BlendModeCompat.SRC_OVER;
60	    }
61	
62	    public boolean hasShadow() {
63	      return shadow != null;
64	    }
65	
66	    public boolean hasColorFilter() {
67	      return colorFilter != null;
68	    }
69	
70	    public boolean isNoop() {
71	      return !isTranslucent() && !hasBlendMode() && !hasShadow() && !hasColorFilter();
72	    }
73	
74	    public void reset() {
75	      alpha = 255;
76	      blendMode = null;
77	      colorFilter = null;
78	      shadow = null;
79	    }
80	  }
