147	  private RenderStrategy chooseRenderStrategy(Canvas parentCanvas, ComposeOp op) {
148	    if (op.isNoop()) {
149	      // Can draw directly onto the final canvas, results will look the same.
150	      return RenderStrategy.DIRECT;
151	    }
152	
153	    if (!op.hasShadow()) {
154	      // Canvas.saveLayer() supports alpha-compositing, blend modes, and color filters, which is
155	      // sufficient for this case, and is faster than manually maintaining an off-screen bitmap.
156	      // It is not clear if it's faster than RENDER_NODE and when, but this is what we've been
157	      // doing prior to OffscreenLayer, so keep that behavior to be safe and avoid regressions.
158	      return RenderStrategy.SAVE_LAYER;
159	    }
160	
161	    // Beyond this point, we are sure that we need to render a drop shadow.
162	
163	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q || !parentCanvas.isHardwareAccelerated()) {
164	      // We don't have support for the RenderNode API, or we're rendering to a software canvas
165	      // which doesn't support RenderNodes anyhow. This is the slowest path: render to a bitmap,
166	      // add a shadow manually on CPU.
167	      return RenderStrategy.BITMAP;
168	    }
169	
170	    if (Build.VERSION.SDK_INT <= Build.VERSION_CODES.S) {
171	      // RenderEffect, which we need for shadows, was only introduced in S. This means that, pre-S,
172	      // we have to do renderShadow() on a bitmap, like in the BITMAP case. However, since it's not
173	      // possible to draw a RenderNode to a software-rendering canvas, there would be no way to get
174	      // our RenderNode contents onto a bitmap where we can renderShadow(). Therefore, fall back to
175	      // full bitmap mode.
176	      return RenderStrategy.BITMAP;
177	    }
178	
179	    // The RenderNode and RenderEffect APIs are available, so use hardware acceleration.
180	    return RenderStrategy.RENDER_NODE;
181	  }
