183	  private Bitmap allocateBitmap(RectF bounds, Bitmap.Config cfg) {
184	    // Add 5% to the width and height before allocating. This avoids repeated
185	    // reallocations in the worst cases of a bitmap growing every frame, while
186	    // still being relatively speedy to blit and operate on.
187	    int width = (int)Math.ceil(bounds.width() * 1.05);
188	    int height = (int)Math.ceil(bounds.height() * 1.05);
189	
190	    // In certain cases the provided bounds can have a width or height of 0, which will cause a runtime crash
191	    // when we try to allocate a Bitmap. To guard against this, use a minimum size of 1x1.
192	    // See https://github.com/airbnb/lottie-android/issues/2620
193	    return Bitmap.createBitmap(Math.max(width, 1), Math.max(height, 1), cfg);
194	  }
195	
196	  private void deallocateBitmap(Bitmap bitmap) {
197	    bitmap.recycle();
198	  }
