200	  private boolean needNewBitmap(@Nullable Bitmap bitmap, RectF bounds) {
201	    if (bitmap == null) {
202	      return true;
203	    }
204	
205	    if (bounds.width() >= bitmap.getWidth() || bounds.height() >= bitmap.getHeight()) {
206	      return true;
207	    }
208	
209	    // If the required area has reduced in size considerably, trigger a reallocation, since
210	    // we might be paying a large unnecessary penalty to work with a bitmap that big.
211	    return bounds.width() < bitmap.getWidth() * 0.75f || bounds.height() < bitmap.getHeight() * 0.75f;
212	  }
