214	  public Canvas start(Canvas parentCanvas, RectF bounds, ComposeOp op) {
215	    if (this.parentCanvas != null) {
216	      throw new IllegalStateException("Cannot nest start() calls on a single OffscreenBitmap - call finish() first");
217	    }
218	
219	    // Determine the scaling applied by the parentCanvas' pre-existing transform matrix. This is an optimization
220	    // to avoid creating bitmaps (or render nodes) with unreasonable sizes that will get scaled down when drawn
221	    // onto parentCanvas anyhow.
222	    if (preExistingTransform == null) preExistingTransform = new float[9];
223	    if (parentCanvasMatrix == null) parentCanvasMatrix = new Matrix();
224	    parentCanvas.getMatrix(parentCanvasMatrix);
225	    parentCanvasMatrix.getValues(preExistingTransform);
226	
227	    float pixelScaleX = preExistingTransform[Matrix.MSCALE_X];
228	    float pixelScaleY = preExistingTransform[Matrix.MSCALE_Y];
229	
230	    if (scaledBounds == null) scaledBounds = new RectF();
231	    scaledBounds.set(
232	        bounds.left * pixelScaleX,
233	        bounds.top * pixelScaleY,
234	        bounds.right * pixelScaleX,
235	        bounds.bottom * pixelScaleY
236	    );
237	
238	    this.parentCanvas = parentCanvas;
239	    this.op = op;
240	    this.currentStrategy = chooseRenderStrategy(parentCanvas, op);
241	    if (this.targetRect == null) this.targetRect = new RectF();
242	    this.targetRect.set((int)bounds.left, (int)bounds.top, (int)bounds.right, (int)bounds.bottom);
243	
244	    if (composePaint == null) composePaint = new LPaint();
245	    composePaint.reset();
246	
247	    Canvas childCanvas;
248	    switch (currentStrategy) {
249	      case DIRECT:
250	        childCanvas = parentCanvas;
251	        childCanvas.save();
252	        break;
253	
254	      case SAVE_LAYER:
255	        // Paint to use for composition
256	        composePaint.setAlpha(op.alpha);
257	        composePaint.setColorFilter(op.colorFilter);
258	        if (op.hasBlendMode()) {
259	          PaintCompat.setBlendMode(composePaint, op.blendMode);
260	        }
261	
262	        // This adds an entry in the parentCanvas stack, will be popped and composited
263	        // when restore() is called
264	        Utils.saveLayerCompat(parentCanvas, bounds, composePaint);
265	        childCanvas = parentCanvas;
266	        break;
267	
268	      case BITMAP:
269	        if (clearPaint == null) {
270	          clearPaint = new LPaint();
271	          clearPaint.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.CLEAR));
272	        }
273	
274	        if (needNewBitmap(bitmap, scaledBounds)) {
275	          if (bitmap != null) {
276	            deallocateBitmap(bitmap);
277	          }
278	          bitmap = allocateBitmap(scaledBounds, Bitmap.Config.ARGB_8888);
279	          bitmapCanvas = new Canvas(bitmap);
280	        } else {
281	          if (bitmapCanvas == null) {
282	            throw new IllegalStateException("If needNewBitmap() returns true, we should have a canvas ready");
283	          }
284	          bitmapCanvas.setMatrix(OffscreenLayer.IDENTITY_MATRIX);
285	          bitmapCanvas.drawRect(-1, -1, scaledBounds.width() + 1, scaledBounds.height() + 1, this.clearPaint);
286	        }
287	
288	        PaintCompat.setBlendMode(composePaint, op.blendMode);
289	        composePaint.setColorFilter(op.colorFilter);
290	        composePaint.setAlpha(op.alpha);
291	
292	        childCanvas = bitmapCanvas;
293	        childCanvas.scale(pixelScaleX, pixelScaleY); // Replicate scaling applied by parentCanvas
294	        childCanvas.translate(-bounds.left, -bounds.top); // So that the image begins at the top-left of the bitmap
295	        break;
296	
297	      case RENDER_NODE:
298	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) {
299	          throw new IllegalStateException("RenderNode not supported but we chose it as render strategy");
300	        }
301	
302	        if (renderNode == null) renderNode = new RenderNode("OffscreenLayer.main");
303	        if (op.hasShadow() && shadowRenderNode == null) {
304	          shadowRenderNode = new RenderNode("OffscreenLayer.shadow");
305	          lastRenderNodeShadow = null;
306	        }
307	
308	        // The render node needs some data in advance
309	        if (op.hasBlendMode() || op.hasColorFilter()) {
310	          composePaint.reset();
311	          PaintCompat.setBlendMode(composePaint, op.blendMode);
312	          composePaint.setColorFilter(op.colorFilter);
313	          renderNode.setUseCompositingLayer(true, composePaint);
314	
315	          if (op.hasShadow()) {
316	            if (shadowRenderNode == null) {
317	              throw new IllegalStateException("Must initialize shadowRenderNode when we have shadow");
318	            }
319	            shadowRenderNode.setUseCompositingLayer(true, composePaint);
320	          }
321	        }
322	        renderNode.setAlpha(op.alpha / 255.f);
323	        if (op.hasShadow()) {
324	          if (shadowRenderNode == null) {
325	            throw new IllegalStateException("Must initialize shadowRenderNode when we have shadow");
326	          }
327	
328	          // lottie-web composes the shadow onto the canvas first, and then the
329	          // contents separately - mirror this behavior
330	          shadowRenderNode.setAlpha(op.alpha / 255.f);
331	        }
332	        renderNode.setHasOverlappingRendering(true);
333	        renderNode.setPosition((int)scaledBounds.left, (int)scaledBounds.top, (int)scaledBounds.right, (int)scaledBounds.bottom);
334	
335	        childCanvas = renderNode.beginRecording((int) scaledBounds.width(), (int) scaledBounds.height());
336	        childCanvas.setMatrix(OffscreenLayer.IDENTITY_MATRIX);
337	        childCanvas.scale(pixelScaleX, pixelScaleY); // Replicate scaling applied by parentCanvas
338	        childCanvas.translate(-bounds.left, -bounds.top); // So that the image begins at the top-left of the bitmap
339	        break;
340	
341	      default:
342	        throw new RuntimeException("Invalid render strategy for OffscreenLayer");
343	    }
344	
345	    return childCanvas;
346	  }
