348	  public void finish() {
349	    if (parentCanvas == null || op == null || preExistingTransform == null || targetRect == null) {
350	      throw new IllegalStateException("OffscreenBitmap: finish() call without matching start()");
351	    }
352	
353	    switch (currentStrategy) {
354	      case DIRECT:
355	      case SAVE_LAYER:
356	        parentCanvas.restore();
357	        break;
358	
359	      case BITMAP:
360	        if (bitmap == null) {
361	          throw new IllegalStateException("Bitmap is not ready; should've been initialized at start() time");
362	        }
363	
364	        if (op.hasShadow()) {
365	          // Composing the shadow first and then the content like this will be incorrect in the
366	          // presence of op.blendMode. However, that is not used at the moment, so this
367	          // optimization is safe. (Otherwise, we'd have to have another bitmap here for the
368	          // intermediate result.)
369	          renderBitmapShadow(parentCanvas, op.shadow);
370	        }
371	
372	        if (bitmapSrcRect == null) bitmapSrcRect = new Rect();
373	        bitmapSrcRect.set(0, 0, (int)(targetRect.width() * preExistingTransform[Matrix.MSCALE_X]), (int)(targetRect.height() * preExistingTransform[Matrix.MSCALE_Y]));
374	        parentCanvas.drawBitmap(bitmap, bitmapSrcRect, targetRect, composePaint);
375	        break;
376	
377	      case RENDER_NODE:
378	        if (renderNode == null) {
379	          throw new IllegalStateException("RenderNode is not ready; should've been initialized at start() time");
380	        }
381	
382	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) {
383	          throw new IllegalStateException("RenderNode not supported but we chose it as render strategy");
384	        }
385	
386	        parentCanvas.save();
387	        parentCanvas.scale(1.0f / preExistingTransform[Matrix.MSCALE_X], 1.0f / preExistingTransform[Matrix.MSCALE_Y]);
388	        renderNode.endRecording();
389	        if (op.hasShadow()) {
390	          // Composing the shadow first and then the content like this will be incorrect in the
391	          // presence of op.blendMode. However, that is not used at the moment, so this
392	          // optimization is safe. (Otherwise, we'd have to have another render node here for the
393	          // intermediate result.)
394	          renderHardwareShadow(parentCanvas, op.shadow);
395	        }
396	        parentCanvas.drawRenderNode(renderNode);
397	        parentCanvas.restore();
398	        break;
399	    }
400	
401	    parentCanvas = null;
402	  }
