404	  private RectF calculateRectIncludingShadow(RectF rect, DropShadow shadow) {
405	    if (rectIncludingShadow == null) rectIncludingShadow = new RectF();
406	    if (tmpRect == null) tmpRect = new RectF();
407	    rectIncludingShadow.set(rect);
408	    rectIncludingShadow.offsetTo(rect.left + shadow.getDx(), rect.top + shadow.getDy());
409	    rectIncludingShadow.inset(-shadow.getRadius(), -shadow.getRadius());
410	    tmpRect.set(rect);
411	    rectIncludingShadow.union(tmpRect);
412	    return rectIncludingShadow;
413	  }
