415	  /** Renders a shadow (only the shadow) of this.bitmap to the provided canvas. */
416	  private void renderBitmapShadow(Canvas targetCanvas, DropShadow shadow) {
417	    if (targetRect == null || bitmap == null) {
418	      throw new IllegalStateException("Cannot render to bitmap outside a start()/finish() block");
419	    }
420	
421	    // This is an expanded rect that encompasses the full extent of the shadow.
422	    RectF rectIncludingShadow = calculateRectIncludingShadow(targetRect, shadow);
423	    if (intRectIncludingShadow == null) intRectIncludingShadow = new Rect();
424	    intRectIncludingShadow.set(
425	        (int)Math.floor(rectIncludingShadow.left),
426	        (int)Math.floor(rectIncludingShadow.top),
427	        (int)Math.ceil(rectIncludingShadow.right),
428	        (int)Math.ceil(rectIncludingShadow.bottom)
429	    );
430	    float pixelScaleX = preExistingTransform != null ? preExistingTransform[Matrix.MSCALE_X] : 1.0f;
431	    float pixelScaleY = preExistingTransform != null ? preExistingTransform[Matrix.MSCALE_Y] : 1.0f;
432	    if (scaledRectIncludingShadow == null) scaledRectIncludingShadow = new RectF();
433	    scaledRectIncludingShadow.set(
434	        rectIncludingShadow.left * pixelScaleX,
435	        rectIncludingShadow.top * pixelScaleY,
436	        rectIncludingShadow.right * pixelScaleX,
437	        rectIncludingShadow.bottom * pixelScaleY
438	    );
439	
440	    if (shadowBitmapSrcRect == null) shadowBitmapSrcRect = new Rect();
441	    shadowBitmapSrcRect.set(0, 0, (int)Math.round(scaledRectIncludingShadow.width()), (int)Math.round(scaledRectIncludingShadow.height()));
442	    if (needNewBitmap(shadowBitmap, scaledRectIncludingShadow)) {
443	      if (shadowBitmap != null) {
444	        deallocateBitmap(shadowBitmap);
445	      }
446	      if (shadowMaskBitmap != null) {
447	        deallocateBitmap(shadowMaskBitmap);
448	      }
449	
450	      shadowBitmap = allocateBitmap(scaledRectIncludingShadow, Bitmap.Config.ARGB_8888);
451	      shadowMaskBitmap = allocateBitmap(scaledRectIncludingShadow, Bitmap.Config.ALPHA_8);
452	      shadowBitmapCanvas = new Canvas(shadowBitmap);
453	      shadowMaskBitmapCanvas = new Canvas(shadowMaskBitmap);
454	    } else {
455	      if (shadowBitmapCanvas == null || shadowMaskBitmapCanvas == null || clearPaint == null) {
456	        throw new IllegalStateException("If needNewBitmap() returns true, we should have a canvas and bitmap ready");
457	      }
458	      shadowBitmapCanvas.drawRect(shadowBitmapSrcRect, clearPaint);
459	      shadowMaskBitmapCanvas.drawRect(shadowBitmapSrcRect, clearPaint);
460	    }
461	
462	    if (shadowMaskBitmap == null) throw new IllegalStateException("Expected to have allocated a shadow mask bitmap");
463	    
464	    if (shadowPaint == null) {
465	      shadowPaint = new LPaint(Paint.ANTI_ALIAS_FLAG);
466	    }
467	
468	    // This is the offset of targetRect inside rectIncludingShadow
469	    float offsetX = targetRect.left - rectIncludingShadow.left;
470	    float offsetY = targetRect.top - rectIncludingShadow.top;
471	
472	    // Draw the image onto the mask layer first. Since the mask layer is ALPHA_8, this discards color information.
473	    // Align it so that when drawn in the end, it originates at targetRect.x, targetRect.y
474	    // the int casts are very important here - they save us from some slow path for non-integer coords
475	    shadowMaskBitmapCanvas.drawBitmap(bitmap, (int)Math.round(offsetX * pixelScaleX), (int)Math.round(offsetY * pixelScaleY), null);
476	
477	    // Prepare the shadow paint. This is the paint that will perform a blur and a tint of the mask
478	    if (shadowBlurFilter == null || lastShadowBlurRadius != shadow.getRadius()) {
479	      float scaledRadius = shadow.getRadius() * (pixelScaleX + pixelScaleY) / 2.0f;
480	      if (scaledRadius > 0) {
481	        shadowBlurFilter = new BlurMaskFilter(scaledRadius, BlurMaskFilter.Blur.NORMAL);
482	      } else {
483	        shadowBlurFilter = null;
484	      }
485	
486	      lastShadowBlurRadius = shadow.getRadius();
487	    }
488	    shadowPaint.setColor(shadow.getColor());
489	    if (shadow.getRadius() > 0.0f) {
490	      shadowPaint.setMaskFilter(shadowBlurFilter);
491	    } else {
492	      shadowPaint.setMaskFilter(null);
493	    }
494	    shadowPaint.setFilterBitmap(true);
495	
496	    // Draw the mask onto our shadowBitmap with the shadowPaint. This bitmap now contains the final
497	    // look of the shadow, correctly positioned inside a rectIncludingShadow-sized area
498	    // the int casts are very important here - they save us from some slow path for non-integer coords
499	    shadowBitmapCanvas.drawBitmap(shadowMaskBitmap, (int)Math.round(shadow.getDx() * pixelScaleX), (int)Math.round(shadow.getDy() * pixelScaleY), shadowPaint);
500	
501	    // Now blit the result onto the final canvas. It might be tempting to skip shadowBitmap and draw the mask
502	    // directly onto the canvas with shadowPaint, but this breaks the blur, since Paint.setMaskFilter() is not
503	    // supported on hardware canvases.
504	    targetCanvas.drawBitmap(shadowBitmap, shadowBitmapSrcRect, intRectIncludingShadow, composePaint);
505	  }
