508	  private void renderHardwareShadow(Canvas targetCanvas, DropShadow shadow) {
509	    if (renderNode == null || shadowRenderNode == null) {
510	      throw new IllegalStateException("Cannot render to render node outside a start()/finish() block");
511	    }
