22	  /**
23	   * Checks the two objects for equality by delegating to their respective
24	   * {@link Object#equals(Object)} methods.
25	   *
26	   * @param o the {@link Pair} to which this one is to be checked for equality
27	   * @return true if the underlying objects of the Pair are both considered
28	   * equal
29	   */
30	  @Override
31	  public boolean equals(Object o) {
32	    if (!(o instanceof Pair)) {
33	      return false;
34	    }
35	    Pair<?, ?> p = (Pair<?, ?>) o;
36	    return objectsEqual(p.first, first) && objectsEqual(p.second, second);
37	  }
38	
39	  private static boolean objectsEqual(Object a, Object b) {
40	    return a == b || (a != null && a.equals(b));
41	  }
